import{_ as p,a0 as r,w as o,s as d,I as e,x as a,a1 as t,A as n,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"在 Linux 下使用 fstrim 延長 SSD 驅動器的壽命 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下使用 fstrim 延長 SSD 驅動器的壽命 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下使用 fstrim 延長 SSD 驅動器的壽命 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下使用 fstrim 延長 SSD 驅動器的壽命 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200212 Extend the life of your SSD drive with fstrim","title":"在 Linux 下使用 fstrim 延長 SSD 驅動器的壽命","tag":"202003","desc":""},"relativePath":"202003/20200212 Extend the life of your SSD drive with fstrim.md","filePath":"[post].md"}'),h={name:"202003/20200212 Extend the life of your SSD drive with fstrim.md"};function u(m,s,b,c,g,f){const i=r("Link");return o(),d("div",null,[s[21]||(s[21]=e("h1",{id:"在-linux-下使用-fstrim-延長-ssd-驅動器的壽命",tabindex:"-1"},[a("在 Linux 下使用 fstrim 延長 SSD 驅動器的壽命 "),e("a",{class:"header-anchor",href:"#在-linux-下使用-fstrim-延長-ssd-驅動器的壽命","aria-label":"Permalink to “在 Linux 下使用 fstrim 延長 SSD 驅動器的壽命”"},"​")],-1)),s[22]||(s[22]=e("blockquote",null,[e("p",null,"這個新的系統服務可以使你的生活更輕鬆。")],-1)),s[23]||(s[23]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202003/04/121625sl380ga10g56d33h.jpg",alt:""})],-1)),e("p",null,[s[1]||(s[1]=a("在過去的十年中，固態驅動器（SSD）帶來了一種管理存儲的新方法。與上一代的轉盤產品相比，SSD 具有無聲、更冷卻的操作和更快的接口規格等優點。當然，新技術帶來了新的維護和管理方法。SSD 具有一種稱為 TRIM 的功能。從本質上講，這是一種用於回收設備上未使用的塊的方法，該塊可能先前已被寫入，但不再包含有效數據，因此可以返回到通用存儲池以供重用。Opensource.com 的 Don Watkins 首先在其 2017 年的文章《",-1)),t(i,{href:"https://linux.cn/article-8177-1.html"},{default:n(()=>[...s[0]||(s[0]=[a("Linux 固態驅動器：為 SSD 啓用 TRIM",-1)])]),_:1}),s[2]||(s[2]=a("》中介紹過 TRIM 的內容。",-1))]),s[24]||(s[24]=l(`<p>如果你一直在 Linux 系統上使用此功能，則你可能熟悉下面描述的兩種方法。</p><h3 id="老的方式" tabindex="-1">老的方式 <a class="header-anchor" href="#老的方式" aria-label="Permalink to “老的方式”">​</a></h3><h4 id="丟棄選項" tabindex="-1">丟棄選項 <a class="header-anchor" href="#丟棄選項" aria-label="Permalink to “丟棄選項”">​</a></h4><p>我最初使用 <code>mount</code> 命令的 <code>discard</code> 選項啓用了此功能。每個文件系統的配置都放在 <code>/etc/fstab</code> 文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /etc/fstab</span></span>
<span class="line"><span>UUID=3453g54-6628-2346-8123435f  /home  xfs  defaults,discard   0 0</span></span></code></pre></div><p>丟棄選項可啓用自動的在線 TRIM。由於可能會對性能造成負面影響，最近關於這是否是最佳方法一直存在爭議。使用此選項會在每次將新數據寫入驅動器時啓動 TRIM。這可能會引入其他磁盤活動，從而影響存儲性能。</p><h4 id="cron-作業" tabindex="-1">Cron 作業 <a class="header-anchor" href="#cron-作業" aria-label="Permalink to “Cron 作業”">​</a></h4><p>我從 <code>fstab</code> 文件中刪除了丟棄選項。然後，我創建了一個 cron 作業來按計劃調用該命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># crontab -l</span></span>
<span class="line"><span>@midnight /usr/bin/trim</span></span></code></pre></div><p>這是我最近在 Ubuntu Linux 系統上使用的方法，直到我瞭解到另一種方法。</p><h3 id="一個新的-trim-服務" tabindex="-1">一個新的 TRIM 服務 <a class="header-anchor" href="#一個新的-trim-服務" aria-label="Permalink to “一個新的 TRIM 服務”">​</a></h3>`,11)),e("p",null,[s[4]||(s[4]=a("我最近發現有一個用於 TRIM 的 systemd 服務。Fedora 在版本 30 中將其",-1)),t(i,{href:"https://fedoraproject.org/wiki/Changes/EnableFSTrimTimer",title:"Fedora Project WIKI: Changes/EnableFSTrimTimer"},{default:n(()=>[...s[3]||(s[3]=[a("引入",-1)])]),_:1}),s[5]||(s[5]=a("，儘管默認情況下在版本 30 和 31 中未啓用它，但計劃在版本 32 中使用它。如果你使用的是 Fedora 工作站 31，並且你想要開始使用此功能，可以非常輕鬆地啓用它。我還將在下面向你展示如何對其進行測試。該服務並非 Fedora 獨有的服務。它是否存在及其地位將因發行版而異。",-1))]),s[25]||(s[25]=l(`<h4 id="測試" tabindex="-1">測試 <a class="header-anchor" href="#測試" aria-label="Permalink to “測試”">​</a></h4><p>我喜歡先進行測試，以更好地瞭解幕後情況。我通過打開終端併發出配置服務調用的命令來執行此操作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/usr/sbin/fstrim --fstab --verbose --quiet</span></span></code></pre></div><p><code>fstrim</code> 的 <code>-help</code> 參數將描述這些信息和其他參數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo /usr/sbin/fstrim --help</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Usage:</span></span>
<span class="line"><span> fstrim [options] &lt;mount point&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Discard unused blocks on a mounted filesystem.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Options:</span></span>
<span class="line"><span> -a, --all           trim all supported mounted filesystems</span></span>
<span class="line"><span> -A, --fstab         trim all supported mounted filesystems from /etc/fstab</span></span>
<span class="line"><span> -o, --offset &lt;num&gt;  the offset in bytes to start discarding from</span></span>
<span class="line"><span> -l, --length &lt;num&gt;  the number of bytes to discard</span></span>
<span class="line"><span> -m, --minimum &lt;num&gt; the minimum extent length to discard</span></span>
<span class="line"><span> -v, --verbose       print number of discarded bytes</span></span>
<span class="line"><span>     --quiet         suppress error messages</span></span>
<span class="line"><span> -n, --dry-run       does everything, but trim</span></span>
<span class="line"><span></span></span>
<span class="line"><span> -h, --help          display this help</span></span>
<span class="line"><span> -V, --version       display version</span></span></code></pre></div><p>因此，現在我可以看到這個 systemd 服務已配置為在我的 <code>/etc/fstab</code> 文件中的所有受支持的掛載文件系統上運行該修剪操作（<code>-fstab</code>），並打印出所丟棄的字節數（<code>-verbose</code>），但是抑制了任何可能會發生的錯誤消息（<code>–quiet</code>）。瞭解這些選項對測試很有幫助。例如，我可以從最安全的方法開始，即空運行。我還將去掉 <code>-quiet</code> 參數，以便確定驅動器設置是否發生任何錯誤。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo /usr/sbin/fstrim --fstab --verbose --dry-run</span></span></code></pre></div><p>這就會顯示 <code>fstrim</code> 命令根據在 <code>/etc/fstab</code> 文件中找到的文件系統要執行的操作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo /usr/sbin/fstrim --fstab --verbose</span></span></code></pre></div><p>現在，這會將 TRIM 操作發送到驅動器，並報告每個文件系統中丟棄的字節數。以下是我最近在新的 NVME SSD 上全新安裝 Fedora 之後的示例。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/home: 291.5 GiB (313011310592 bytes) trimmed on /dev/mapper/wkst-home</span></span>
<span class="line"><span>/boot/efi: 579.2 MiB (607301632 bytes) trimmed on /dev/nvme0n1p1</span></span>
<span class="line"><span>/boot: 787.5 MiB (825778176 bytes) trimmed on /dev/nvme0n1p2</span></span>
<span class="line"><span>/: 60.7 GiB (65154805760 bytes) trimmed on /dev/mapper/wkst-root</span></span></code></pre></div><h4 id="啓用" tabindex="-1">啓用 <a class="header-anchor" href="#啓用" aria-label="Permalink to “啓用”">​</a></h4><p>Fedora Linux 實現了一個計劃每週運行它的 systemd 計時器服務。要檢查其是否存在及當前狀態，請運行 <code>systemctl status</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status fstrim.timer</span></span></code></pre></div><p>現在，啓用該服務。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable fstrim.timer</span></span></code></pre></div><h4 id="驗證" tabindex="-1">驗證 <a class="header-anchor" href="#驗證" aria-label="Permalink to “驗證”">​</a></h4><p>然後，你可以通過列出所有計時器來驗證該計時器是否已啓用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl list-timers --all</span></span></code></pre></div><p>會顯示出下列行，表明 <code>fstrim.timer</code> 存在。注意，該計時器實際上激活了 <code>fstrim.service</code> 服務。這是實際調用 <code>fstrim</code> 的地方。與時間相關的字段顯示為 <code>n/a</code>，因為該服務已啓用且尚未運行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NEXT   LEFT    LAST   PASSED   UNIT           ACTIVATES</span></span>
<span class="line"><span>n/a    n/a     n/a    n/a      fstrim.timer   fstrim.service</span></span></code></pre></div><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>該服務似乎是在驅動器上運行 TRIM 的最佳方法。這比必須創建自己的 crontab 條目來調用 <code>fstrim</code> 命令要簡單得多。不必編輯 <code>fstab</code> 文件也更安全。觀察固態存儲技術的發展很有趣，並且我很高興看到 Linux 似乎正在朝着標準且安全的方向實現它。</p><p>在本文中，學習了固態驅動器與傳統硬盤驅動器有何不同以及它的含義...</p><hr>`,25)),e("p",null,[s[7]||(s[7]=a("via: ",-1)),t(i,{href:"https://opensource.com/article/20/2/trim-solid-state-storage-linux"},{default:n(()=>[...s[6]||(s[6]=[a("https://opensource.com/article/20/2/trim-solid-state-storage-linux",-1)])]),_:1})]),e("p",null,[s[12]||(s[12]=a("作者：",-1)),t(i,{href:"https://opensource.com/users/alanfdoss"},{default:n(()=>[...s[8]||(s[8]=[a("Alan Formy-Duval",-1)])]),_:1}),s[13]||(s[13]=a(" 選題：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[9]||(s[9]=[a("lujun9972",-1)])]),_:1}),s[14]||(s[14]=a(" 譯者：",-1)),t(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1}),s[15]||(s[15]=a(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[11]||(s[11]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[18]||(s[18]=a("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[16]||(s[16]=[a("LCTT",-1)])]),_:1}),s[19]||(s[19]=a(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:n(()=>[...s[17]||(s[17]=[a("Linux中國",-1)])]),_:1}),s[20]||(s[20]=a(" 榮譽推出",-1))])])}const T=p(h,[["render",u]]);export{x as __pageData,T as default};
